314	static int AsLexInput(SourceMgr &SrcMgr, MCAsmInfo &MAI,
315	                      raw_ostream &OS) {
316	
317	  AsmLexer Lexer(MAI);
318	  Lexer.setBuffer(SrcMgr.getMemoryBuffer(SrcMgr.getMainFileID())->getBuffer());
319	
320	  bool Error = false;
321	  while (Lexer.Lex().isNot(AsmToken::Eof)) {
322	    Lexer.getTok().dump(OS);
323	    OS << "\n";
324	    if (Lexer.getTok().getKind() == AsmToken::Error)
325	      Error = true;
326	  }
327	
328	  return Error;
329	}
