381	int main(int argc, char **argv) {
382	  InitLLVM X(argc, argv);
383	
384	  // Initialize targets and assembly printers/parsers.
385	  llvm::InitializeAllTargetInfos();
386	  llvm::InitializeAllTargetMCs();
387	  llvm::InitializeAllAsmParsers();
388	  llvm::InitializeAllDisassemblers();
389	
390	  // Register the target printer for --version.
391	  cl::AddExtraVersionPrinter(TargetRegistry::printRegisteredTargetsForVersion);
392	
393	  cl::HideUnrelatedOptions({&MCCategory, &getColorCategory()});
394	  cl::ParseCommandLineOptions(argc, argv, "llvm machine code playground\n");
395	
396	  if (TimeTrace)
397	    timeTraceProfilerInitialize(TimeTraceGranularity, argv[0]);
398	
399	  llvm::scope_exit TimeTraceScopeExit([]() {
400	    if (!TimeTrace)
401	      return;
402	    if (auto E = timeTraceProfilerWrite(TimeTraceFile, OutputFilename)) {
403	      logAllUnhandledErrors(std::move(E), errs());
404	      return;
405	    }
406	    timeTraceProfilerCleanup();
407	  });
408	
409	  MCTargetOptions MCOptions = mc::InitMCTargetOptionsFromFlags();
410	  MCOptions.CompressDebugSections = CompressDebugSections.getValue();
411	  MCOptions.ShowMCInst = ShowInst;
412	  MCOptions.AsmVerbose = true;
413	  MCOptions.MCNoExecStack = NoExecStack;
414	  MCOptions.MCUseDwarfDirectory = MCTargetOptions::EnableDwarfDirectory;
415	  MCOptions.InstPrinterOptions = InstPrinterOptions;
416	  if (OutputAsmVariant.getNumOccurrences())
417	    MCOptions.OutputAsmVariant = OutputAsmVariant;
418	
419	  setDwarfDebugFlags(argc, argv);
420	  setDwarfDebugProducer();
421	
422	  const char *ProgName = argv[0];
423	  const Target *TheTarget = GetTarget(ProgName);
424	  if (!TheTarget)
425	    return 1;
426	  // Now that GetTarget() has (potentially) replaced TripleName, it's safe to
427	  // construct the Triple object.
428	  Triple TheTriple(TripleName);
429	
430	  ErrorOr<std::unique_ptr<MemoryBuffer>> BufferPtr =
431	      MemoryBuffer::getFileOrSTDIN(InputFilename, /*IsText=*/true);
432	  if (std::error_code EC = BufferPtr.getError()) {
433	    WithColor::error(errs(), ProgName)
434	        << InputFilename << ": " << EC.message() << '\n';
435	    return 1;
436	  }
437	  MemoryBuffer *Buffer = BufferPtr->get();
438	
439	  SourceMgr SrcMgr;
440	
441	  // Tell SrcMgr about this buffer, which is what the parser will pick up.
442	  SrcMgr.AddNewSourceBuffer(std::move(*BufferPtr), SMLoc());
443	
444	  // Record the location of the include directories so that the lexer can find
445	  // it later.
446	  SrcMgr.setIncludeDirs(IncludeDirs);
447	  SrcMgr.setVirtualFileSystem(vfs::getRealFileSystem());
448	
449	  std::unique_ptr<MCRegisterInfo> MRI(TheTarget->createMCRegInfo(TheTriple));
450	  assert(MRI && "Unable to create target register info!");
451	
452	  std::unique_ptr<MCAsmInfo> MAI(
453	      TheTarget->createMCAsmInfo(*MRI, TheTriple, MCOptions));
454	  assert(MAI && "Unable to create target asm info!");
455	
456	  if (CompressDebugSections != DebugCompressionType::None) {
457	    if (const char *Reason = compression::getReasonIfUnsupported(
458	            compression::formatFor(CompressDebugSections))) {
459	      WithColor::error(errs(), ProgName)
460	          << "--compress-debug-sections: " << Reason;
461	      return 1;
462	    }
463	  }
464	  MAI->setPreserveAsmComments(PreserveComments);
465	  MAI->setCommentColumn(CommentColumn);
466	
467	  // Package up features to be passed to target/subtarget
468	  SubtargetFeatures Features;
469	  std::string FeaturesStr;
470	
471	  // Replace -mcpu=native with Host CPU and features.
472	  if (MCPU == "native") {
473	    MCPU = std::string(llvm::sys::getHostCPUName());
474	
475	    llvm::StringMap<bool> TargetFeatures = llvm::sys::getHostCPUFeatures();
476	    for (auto const &[FeatureName, IsSupported] : TargetFeatures)
477	      Features.AddFeature(FeatureName, IsSupported);
478	  }
479	
480	  // Handle features passed to target/subtarget.
481	  for (unsigned i = 0; i != MAttrs.size(); ++i)
482	    Features.AddFeature(MAttrs[i]);
483	  FeaturesStr = Features.getString();
484	
485	  std::unique_ptr<MCSubtargetInfo> STI(
486	      TheTarget->createMCSubtargetInfo(TheTriple, MCPU, FeaturesStr));
487	  if (!STI) {
488	    WithColor::error(errs(), ProgName) << "unable to create subtarget info\n";
489	    return 1;
490	  }
491	
492	  // FIXME: This is not pretty. MCContext has a ptr to MCObjectFileInfo and
493	  // MCObjectFileInfo needs a MCContext reference in order to initialize itself.
494	  MCContext Ctx(TheTriple, *MAI, *MRI, *STI, &SrcMgr);
495	  std::unique_ptr<MCObjectFileInfo> MOFI(
496	      TheTarget->createMCObjectFileInfo(Ctx, PIC, LargeCodeModel));
497	  Ctx.setObjectFileInfo(MOFI.get());
498	
499	  Ctx.setGenDwarfForAssembly(GenDwarfForAssembly);
500	  // Default to 4 for dwarf version.
501	  unsigned DwarfVersion = MCOptions.DwarfVersion ? MCOptions.DwarfVersion : 4;
502	  if (DwarfVersion < 2 || DwarfVersion > 6) {
503	    errs() << ProgName << ": Dwarf version " << DwarfVersion
504	           << " is not supported." << '\n';
505	    return 1;
506	  }
507	  Ctx.setDwarfVersion(DwarfVersion);
508	  if (MCOptions.Dwarf64) {
509	    // The 64-bit DWARF format was introduced in DWARFv3.
510	    if (DwarfVersion < 3) {
511	      errs() << ProgName
512	             << ": the 64-bit DWARF format is not supported for DWARF versions "
513	                "prior to 3\n";
514	      return 1;
515	    }
516	    // 32-bit targets don't support DWARF64, which requires 64-bit relocations.
517	    if (MAI->getCodePointerSize() < 8) {
518	      errs() << ProgName
519	             << ": the 64-bit DWARF format is only supported for 64-bit "
520	                "targets\n";
521	      return 1;
522	    }
523	    // If needsDwarfSectionOffsetDirective is true, we would eventually call
524	    // MCStreamer::emitSymbolValue() with IsSectionRelative = true, but that
525	    // is supported only for 4-byte long references.
526	    if (MAI->needsDwarfSectionOffsetDirective()) {
527	      errs() << ProgName << ": the 64-bit DWARF format is not supported for "
528	             << TheTriple.normalize() << "\n";
529	      return 1;
530	    }
531	    Ctx.setDwarfFormat(dwarf::DWARF64);
532	  }
533	  if (!DwarfDebugFlags.empty())
534	    Ctx.setDwarfDebugFlags(StringRef(DwarfDebugFlags));
535	  if (!DwarfDebugProducer.empty())
536	    Ctx.setDwarfDebugProducer(StringRef(DwarfDebugProducer));
537	  if (!DebugCompilationDir.empty())
538	    Ctx.setCompilationDir(DebugCompilationDir);
539	  else {
540	    // If no compilation dir is set, try to use the current directory.
541	    SmallString<128> CWD;
542	    if (!sys::fs::current_path(CWD))
543	      Ctx.setCompilationDir(CWD);
544	  }
545	  for (const auto &Arg : DebugPrefixMap) {
546	    const auto &KV = StringRef(Arg).split('=');
547	    Ctx.addDebugPrefixMapEntry(std::string(KV.first), std::string(KV.second));
548	  }
549	  if (!MainFileName.empty())
550	    Ctx.setMainFileName(MainFileName);
551	  if (GenDwarfForAssembly)
552	    Ctx.setGenDwarfRootFile(InputFilename, Buffer->getBuffer());
553	
554	  sys::fs::OpenFlags Flags = (FileType == OFT_AssemblyFile)
555	                                 ? sys::fs::OF_TextWithCRLF
556	                                 : sys::fs::OF_None;
557	  std::unique_ptr<ToolOutputFile> Out = GetOutputStream(OutputFilename, Flags);
558	  if (!Out)
559	    return 1;
560	
561	  std::unique_ptr<ToolOutputFile> DwoOut;
562	  if (!SplitDwarfFile.empty()) {
563	    if (FileType != OFT_ObjectFile) {
564	      WithColor::error() << "dwo output only supported with object files\n";
565	      return 1;
566	    }
567	    DwoOut = GetOutputStream(SplitDwarfFile, sys::fs::OF_None);
568	    if (!DwoOut)
569	      return 1;
570	  }
571	
572	  std::unique_ptr<buffer_ostream> BOS;
573	  raw_pwrite_stream *OS = &Out->os();
574	  std::unique_ptr<MCStreamer> Str;
575	
576	  std::unique_ptr<MCInstrInfo> MCII(TheTarget->createMCInstrInfo());
577	  assert(MCII && "Unable to create instruction info!");
578	
579	  std::unique_ptr<MCInstPrinter> IP;
580	  if (ValidateCFI) {
581	    // TODO: The DWARF CFI checker support for emitting anything other than
582	    // errors and warnings has not been implemented yet. Because of this, it is
583	    // assert-checked that the filetype output is null.
584	    assert(FileType == OFT_Null);
585	    auto FFA = std::make_unique<CFIFunctionFrameAnalyzer>(Ctx, *MCII);
586	    auto FFS = std::make_unique<CFIFunctionFrameStreamer>(Ctx, std::move(FFA));
587	    TheTarget->createNullTargetStreamer(*FFS);
588	    Str = std::move(FFS);
589	  } else if (FileType == OFT_AssemblyFile) {
590	    unsigned AsmVariant = MAI->getOutputAssemblerDialect();
591	    IP.reset(TheTarget->createMCInstPrinter(Triple(TripleName), AsmVariant,
592	                                            *MAI, *MCII, *MRI));
593	
594	    if (!IP) {
595	      WithColor::error()
596	          << "unable to create instruction printer for target triple '"
597	          << TheTriple.normalize() << "' with assembly variant " << AsmVariant
598	          << "\n";
599	      return 1;
600	    }
601	
602	    for (StringRef Opt : InstPrinterOptions)
603	      if (!IP->applyTargetSpecificCLOption(Opt)) {
604	        WithColor::error() << "invalid InstPrinter option '" << Opt << "'\n";
605	        return 1;
606	      }
607	
608	    // Set the display preference for hex vs. decimal immediates.
609	    IP->setPrintImmHex(PrintImmHex);
610	
611	    switch (Action) {
612	    case AC_MDisassemble:
613	      IP->setUseMarkup(true);
614	      break;
615	    case AC_CDisassemble:
616	      IP->setUseColor(true);
617	      break;
618	    default:
619	      break;
620	    }
621	
622	    // Set up the AsmStreamer.
623	    std::unique_ptr<MCCodeEmitter> CE;
624	    if (ShowEncoding)
625	      CE.reset(TheTarget->createMCCodeEmitter(*MCII, Ctx));
626	
627	    std::unique_ptr<MCAsmBackend> MAB(
628	        TheTarget->createMCAsmBackend(*STI, *MRI, MCOptions));
629	    auto FOut = std::make_unique<formatted_raw_ostream>(*OS);
630	    Str.reset(TheTarget->createAsmStreamer(Ctx, std::move(FOut), std::move(IP),
631	                                           std::move(CE), std::move(MAB)));
632	
633	    Triple T(TripleName);
634	    if (T.isLFI())
635	      initializeLFIMCStreamer(*Str.get(), Ctx, T);
636	  } else if (FileType == OFT_Null) {
637	    Str.reset(TheTarget->createNullStreamer(Ctx));
638	  } else {
639	    assert(FileType == OFT_ObjectFile && "Invalid file type!");
640	
641	    if (!Out->os().supportsSeeking()) {
642	      BOS = std::make_unique<buffer_ostream>(Out->os());
643	      OS = BOS.get();
644	    }
645	
646	    MCCodeEmitter *CE = TheTarget->createMCCodeEmitter(*MCII, Ctx);
647	    MCAsmBackend *MAB = TheTarget->createMCAsmBackend(*STI, *MRI, MCOptions);
648	    Str.reset(TheTarget->createMCObjectStreamer(
649	        TheTriple, Ctx, std::unique_ptr<MCAsmBackend>(MAB),
650	        DwoOut ? MAB->createDwoObjectWriter(*OS, DwoOut->os())
651	               : MAB->createObjectWriter(*OS),
652	        std::unique_ptr<MCCodeEmitter>(CE), *STI));
653	    Str->emitVersionForTarget(TheTriple, VersionTuple(), nullptr,
654	                              VersionTuple());
655	  }
656	
657	  int Res = 1;
658	  bool disassemble = false;
659	  switch (Action) {
660	  case AC_AsLex:
661	    Res = AsLexInput(SrcMgr, *MAI, Out->os());
662	    break;
663	  case AC_Assemble:
664	    Res = AssembleInput(ProgName, TheTarget, SrcMgr, Ctx, *Str, *MAI, *STI,
665	                        *MCII, MCOptions);
666	    break;
667	  case AC_MDisassemble:
668	  case AC_CDisassemble:
669	  case AC_Disassemble:
670	    disassemble = true;
671	    break;
672	  }
673	  if (disassemble)
674	    Res = Disassembler::disassemble(*TheTarget, *STI, *Str, *Buffer, SrcMgr,
675	                                    Ctx, HexBytes, NumBenchmarkRuns);
676	
677	  // Keep output if no errors.
678	  if (Res == 0) {
679	    Out->keep();
680	    if (DwoOut)
681	      DwoOut->keep();
682	  }
683	
684	  return Res;
685	}
