147	                             unsigned Flags, unsigned Isa,
148	                             unsigned Discriminator, StringRef FileName,
149	                             StringRef Comment = {}) override;
150	  void emitDwarfAdvanceLineAddr(int64_t LineDelta, const MCSymbol *LastLabel,
151	                                const MCSymbol *Label,
152	                                unsigned PointerSize) override;
153	  void emitDwarfLineEndEntry(MCSection *Section, MCSymbol *LastLabel,
154	                             MCSymbol *EndLabel = nullptr) override;
155	  void emitDwarfAdvanceFrameAddr(const MCSymbol *LastLabel,
156	                                 const MCSymbol *Label, SMLoc Loc);
157	  void emitSFrameCalculateFuncOffset(const MCSymbol *FunCabsel,
158	                                     const MCSymbol *FREBegin,
